-- Endloop test board: move roast lines to the slot model (2026-10-12).
-- Run once in the Supabase SQL editor, after roast-admin.sql. Do NOT re-run seed.sql afterwards.
--
-- What changes
--   * Every app line now belongs to a slot (category, level, app kinds, roaster). The row id is the
--     language plus the slot: en_lh_s03 and ta_lh_s03 are the English and Tanglish lines of slot lh_s03.
--   * 74 Tanglish lines move to the slot whose idea they match (their old number pointed at a
--     different English line). Reviews, notes and proposed changes move with their line.
--   * Adds 44 new Tanglish lines and 2 new slots in both languages, plus status (live / draft / off)
--     and an order number on every line.
--   * Tester suggestions that point at a moved Tanglish line are pointed at its new id.
--   * Lines testers suggested as new (ids like en_new_001) are left alone.
begin;

create temp table _old on commit drop as select id, data from public.roasts;

insert into public.roasts (id, data)
select v.id,
       v.data || coalesce((
         select jsonb_strip_nulls(jsonb_build_object(
           'review', o.data->'review', 'proposed', o.data->'proposed', 'notes', o.data->'notes',
           'reviewedBy', o.data->'reviewedBy', 'reviewedAt', o.data->'reviewedAt'))
         from _old o where o.id = v.old_id), '{}'::jsonb)
